import{z as p,x as r,o as s,c,q as o,j as n,D as a,d,s as i,S as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"namespaces","description":"","frontmatter":{"title":"namespaces","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/namespaces.md","filePath":"cs/namespaces.md","lastUpdated":1791063341000}'),l={name:"cs/namespaces.md"};function B(A,e,m,_,u,h){const E=r("Mermaid");return s(),c("div",null,[e[2]||(e[2]=o('<h1 id="namespaces" tabindex="-1">namespaces <a class="header-anchor" href="#namespaces" aria-label="Permalink to &quot;namespaces&quot;">​</a></h1><div class="epigraph"><p>命名空间让一组进程看见自己的 pid、挂载树、网络栈、IPC、UTS 名和用户 id 映射，而不是全局那一份。</p><footer>—— 据 Linux namespaces 文档；POSIX 未规定的 Linux 扩展，以内核文档为准</footer></div><p><a href="/cs/init-userspace">上一课</a>的 pid 1 是全局的。<a href="/cs/mount-super">挂载</a> 的树也是全局的。容器想「像一台机」又不跑第二次内核。缺口是 <strong>namespaces</strong>：隔离的是名字与视图，不是 CPU 时间配额（那是 cgroup）。本课合并六类常用空间，不当六篇词条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>chroot</code> 只改路径起点，pid 与网络仍全局。缺口：<code>clone</code>/<code>unshare</code> 带 <code>CLONE_NEWPID</code> 等标志，子进程成为该空间的 pid 1，看不见外面的进程表；<code>CLONE_NEWNS</code> 得到挂载副本；<code>CLONE_NEWNET</code> 有自己的网卡与回环；UTS 改 hostname；IPC 隔离 System V/POSIX 对象；user 命名空间映射容器内 uid 0 到外层非特权——机制课只讲映射存在，不讲如何打穿。</p><p><span class="marginnote">术语翻译：namespaces 就是给每组进程发一副「过滤眼镜」——进程表、挂载树、网卡、主机名各有各的一份视图，内核记账时把同一个对象在不同眼镜里登记成不同编号。它隔离的是「看见什么」，不是「能用多少」。</span></p><p><span class="marginnote">setns 加入已有空间。打开 <code>/proc/pid/ns/*</code> 可引用。本课不写逃逸步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建容器：先 user（若需要），再 pid/mnt/net 等，在新 pid 空间 exec 一个 init。该 init 只 wait 自己空间的孩子。挂载空间里可以有独立的 <code>/proc</code>，否则 pid 视图与 proc 不一致。与 <a href="/cs/file-table">文件表</a> 对照：fd 仍可在某些操作中指向外层对象，能力边界由实现规定，主干不展开利用。</p>',9)),(s(),n(t,null,{default:a(()=>[i(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLONE%5B%22clone%2Funshare%22%5D%20--%3E%20PIDNS%5B%22%E8%87%AA%E5%B7%B1%E7%9A%84%20pid%20%E6%A0%91%22%5D%0A%20%20CLONE%20--%3E%20MNT%5B%22%E8%87%AA%E5%B7%B1%E7%9A%84%E6%8C%82%E8%BD%BD%E6%A0%91%22%5D%0A%20%20CLONE%20--%3E%20NET%5B%22%E8%87%AA%E5%B7%B1%E7%9A%84%E7%BD%91%E7%BB%9C%E6%A0%88%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>命名空间把「全局内核表格」变成每组进程一份视图，让 <a href="/cs/vfs">VFS</a> 查找、<code>kill</code> 的 pid、<code>bind</code> 的端口号重新解释。内核仍是一份，特权环未变。这与虚拟机不同：没有第二套页表根给「客内核」。user ns 降低了「容器内 root」对外层的含义，安全课会再收。</p><p><span class="marginnote">常见误区：初学者以为容器里跑着第二个内核，或者容器内的 pid 1 就是宿主机的 pid 1。实际上内核只有一份，宿主机上 <code>ps</code> 仍能看到容器里的全部进程（编号可能不同）；pid 1 只在容器视图内成立，<code>kill</code>、<code>bind</code> 都按各自视图解释。</span></p><p><span class="marginnote">为什么重要：视图隔离解决不了争用——两个容器各自以为自己独占机器，实际仍在抢同一份 CPU 和物理内存。这也是 namespaces 与 cgroup 必须配合的原因：前者切视图，后者记账与限流，缺一个都不算完整的容器化。</span></p>',4)),(s(),n(t,null,{default:a(()=>[i(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20PROC%5B%22%E5%AE%B9%E5%99%A8%E5%86%85%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20V1%5B%22%E5%AE%B9%E5%99%A8%20pid%20%E8%A7%86%E5%9B%BE%EF%BC%9A%E7%BC%96%E5%8F%B7%201%22%5D%0A%20%20PROC%20--%3E%20V2%5B%22%E5%AE%BF%E4%B8%BB%E6%9C%BA%E8%A7%86%E5%9B%BE%EF%BC%9A%E7%9C%9F%E5%AE%9E%E7%BC%96%E5%8F%B7%EF%BC%88%E5%A6%82%203579%EF%BC%89%22%5D%0A%20%20V1%20--%3E%20K%5B%22%E5%AE%B9%E5%99%A8%E5%86%85%20kill%201%20%E5%91%BD%E4%B8%AD%E5%AE%83%22%5D%0A%20%20V2%20--%3E%20H%5B%22%E5%AE%BF%E4%B8%BB%E6%9C%BA%20ps%20%E6%98%BE%E7%A4%BA%203579%22%5D%0A%20%20OUT%5B%22%E5%AE%BF%E4%B8%BB%E6%9C%BA%E5%85%B6%E4%BB%96%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20INV%5B%22%E5%AE%B9%E5%99%A8%E8%A7%86%E5%9B%BE%E9%87%8C%E6%A0%B9%E6%9C%AC%E7%9C%8B%E4%B8%8D%E8%A7%81%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 time 命名空间的全部细节。不保证所有资源都有命名空间（如某些设备号）。下一课：视图隔离不解 CPU/内存/IO 争用，需要分组记账与限制。</p><p>后课默认：名字可以按组切开。CPU 与内存配额，下一课 cgroups。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>namespaces 隔离 pid、挂载、网络等视图，内核仍一份。</li><li>容器内 pid 1 只覆盖该空间。</li><li>资源限制是 cgroup 的缺口。</li><li>出处：Linux <code>namespaces(7)</code>；Love 之后的内核文档；Tanenbaum <em>MOS</em> 对容器的讨论。</li></ul>',5))])}const T=p(l,[["render",B]]);export{f as __pageData,T as default};
